from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def purge_expired(t):
        expired_keys = [k for k, (v, wt) in cache.items() if t >= wt + ttl]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        kind = op[0]
        t = op[1]
        if kind == 'put':
            key = op[2]
            value = op[3]
            purge_expired(t)
            if key in cache:
                del cache[key]
            elif len(cache) >= capacity:
                cache.popitem(last=False)
            cache[key] = (value, t)
        elif kind == 'get':
            key = op[2]
            purge_expired(t)
            if key in cache:
                value, wt = cache[key]
                del cache[key]
                cache[key] = (value, wt)
                results.append(value)
            else:
                results.append(-1)
        else:
            raise ValueError("Unknown op type: " + str(kind))

    return results

